import{_ as r,o as s,c as e,ak as a}from"./chunks/framework.BHDkgpnK.js";const c=JSON.parse('{"title":"KossJS 社区 FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"zh/community/COMMUNITY_FAQ.md","filePath":"zh/community/COMMUNITY_FAQ.md","lastUpdated":1783919437000}'),o={name:"zh/community/COMMUNITY_FAQ.md"};function n(i,t,l,g,d,h){return s(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="kossjs-社区-faq" tabindex="-1">KossJS 社区 FAQ <a class="header-anchor" href="#kossjs-社区-faq" aria-label="Permalink to “KossJS 社区 FAQ”">​</a></h1><blockquote><p><strong>编者注</strong>：本文档整理自 KossJS 作者跟部分有意愿使用 KossJS 的开发者在群聊中的发言，旨在帮助社区用户更清晰地理解项目的设计边界、维护策略和推荐用法。内容已被作者明确允许。</p></blockquote><hr><h2 id="关于这份-faq" tabindex="-1">关于这份 FAQ <a class="header-anchor" href="#关于这份-faq" aria-label="Permalink to “关于这份 FAQ”">​</a></h2><blockquote><p>官方文档介绍的是 KossJS “设计成什么样” 以及 “如何使用”，这份 FAQ 补充的是作者 “实际维护中怎么想”。两者不冲突，建议配合阅读。</p></blockquote><hr><h2 id="_1-项目现状与代码质量" tabindex="-1">1. 项目现状与代码质量 <a class="header-anchor" href="#_1-项目现状与代码质量" aria-label="Permalink to “1. 项目现状与代码质量”">​</a></h2><h3 id="q1-kossjs-的代码是纯手工写的吗-我可以信任它吗" tabindex="-1">Q1：KossJS 的代码是纯手工写的吗？我可以信任它吗？ <a class="header-anchor" href="#q1-kossjs-的代码是纯手工写的吗-我可以信任它吗" aria-label="Permalink to “Q1：KossJS 的代码是纯手工写的吗？我可以信任它吗？”">​</a></h3><p><strong>A</strong>：代码主要由 <strong>AI 辅助生成</strong>，作者本人会进行部分代码的审查，但<strong>作者不擅长 Rust</strong>（能看懂部分但不会修改，也无法确定 Rust 代码是否正确）。因此：</p><ul><li>JS 层（<em><strong>src/js_shims/</strong></em>）和 Python 测试：作者完全能审，可信度较高。</li><li>Rust 胶水层（<em><strong>src/runtime.rs</strong></em>、<em><strong>src/sandbox.rs</strong></em>、<em><strong>src/module_loader.rs</strong></em>、<em><strong>src/resolver.rs</strong></em>、<em><strong>src/_senri_ffi/</strong></em> 等）：作者看不太懂，可能存在 AI 生成的边界错误，欢迎社区 Rust 开发者帮忙 Review。</li></ul><h3 id="q2-现在能上生产环境吗" tabindex="-1">Q2：现在能上生产环境吗？ <a class="header-anchor" href="#q2-现在能上生产环境吗" aria-label="Permalink to “Q2：现在能上生产环境吗？”">​</a></h3><p><strong>A</strong>：<strong>不建议</strong>。当前版本（0.1.0-dev.x）是开发预览版，仅供测试尝鲜。建议等到正式发布的版本，且 Rust 胶水层经过社区充分 Review 后再用于生产。</p><hr><h2 id="_2-ffi-senri-ffi-与原生调用" tabindex="-1">2. FFI（<em><strong>_senri_ffi</strong></em>）与原生调用 <a class="header-anchor" href="#_2-ffi-senri-ffi-与原生调用" aria-label="Permalink to “2. FFI（_senri_ffi）与原生调用”">​</a></h2><h3 id="q3-kossjs-内置的-senri-ffi-能在桌面端用吗" tabindex="-1">Q3：KossJS 内置的 <em><strong>_senri_ffi</strong></em> 能在桌面端用吗？ <a class="header-anchor" href="#q3-kossjs-内置的-senri-ffi-能在桌面端用吗" aria-label="Permalink to “Q3：KossJS 内置的 _senri_ffi 能在桌面端用吗？”">​</a></h3><p><strong>A</strong>：<strong>不推荐</strong>。虽然它能用，但：</p><ul><li>依赖 <em><strong>libffi</strong></em>，跨平台（尤其不同 glibc 版本）调试极其困难。</li><li>一旦出问题（段错误、堆栈撕裂），作者因不熟 Rust 和 <em><strong>libffi</strong></em> 内部机制，<strong>无法修复</strong>。</li><li>作者建议：<strong>在宿主层（Python/C++/C#）直接调用动态库，然后通过 <em><strong>koss_register_function</strong></em> 绑定给 JS。</strong></li></ul><h3 id="q4-senri-ffi-在移动端-android-ios-harmonyos-支持吗" tabindex="-1">Q4：<em><strong>_senri_ffi</strong></em> 在移动端（Android/iOS/HarmonyOS）支持吗？ <a class="header-anchor" href="#q4-senri-ffi-在移动端-android-ios-harmonyos-支持吗" aria-label="Permalink to “Q4：_senri_ffi 在移动端（Android/iOS/HarmonyOS）支持吗？”">​</a></h3><p><strong>A</strong>：<strong>不支持</strong>。移动端加载外部动态库本身就很麻烦（iOS 签名限制、Android ABI 匹配），且作者没有足够的移动端测试环境。<strong>移动端请务必走“宿主封装 + 注册函数”的路线。</strong></p><h3 id="q5-如果我非要开-stable-false-用-ffi-出了问题怎么办" tabindex="-1">Q5：如果我非要开 <em><strong>stable=False</strong></em> 用 FFI，出了问题怎么办？ <a class="header-anchor" href="#q5-如果我非要开-stable-false-用-ffi-出了问题怎么办" aria-label="Permalink to “Q5：如果我非要开 stable=False 用 FFI，出了问题怎么办？”">​</a></h3><p><strong>A</strong>：<strong>作者会看 Issue，但大概率修不了。</strong> 因为 Rust + <em><strong>libffi</strong></em> 的调试堆栈信息极其模糊，作者缺乏定位能力。<strong>强烈建议放弃，走宿主封装。</strong></p><hr><h2 id="_3-worker-多线程" tabindex="-1">3. Worker（多线程） <a class="header-anchor" href="#_3-worker-多线程" aria-label="Permalink to “3. Worker（多线程）”">​</a></h2><h3 id="q6-kossjs-的-worker-功能稳定吗" tabindex="-1">Q6：KossJS 的 Worker 功能稳定吗？ <a class="header-anchor" href="#q6-kossjs-的-worker-功能稳定吗" aria-label="Permalink to “Q6：KossJS 的 Worker 功能稳定吗？”">​</a></h3><p><strong>A</strong>：<strong>自 v0.1.0-dev.10 起已整体移除。</strong> 早期版本的 Worker 线程池测试覆盖不全、且未传播沙箱设置（能力位、审核回调），作者已在 dev.10 将其彻底删除（含 <code>worker_threads</code>、<code>__koss_worker_*</code>、<code>KOSS_CAP_WORKER</code>）。需要并行执行任务时，请使用多实例隔离或异步执行（见 <a href="/KossJS/zh/reference/stable-alternatives.html#二并行执行替代方案">stable 模式替代方案 - 并行执行</a>）。</p><hr><h2 id="_4-安全模型-capability-与-audit" tabindex="-1">4. 安全模型（Capability 与 Audit） <a class="header-anchor" href="#_4-安全模型-capability-与-audit" aria-label="Permalink to “4. 安全模型（Capability 与 Audit）”">​</a></h2><h3 id="q8-能力位-capability-是怎么工作的-是运行时检查吗" tabindex="-1">Q8：能力位（Capability）是怎么工作的？是运行时检查吗？ <a class="header-anchor" href="#q8-能力位-capability-是怎么工作的-是运行时检查吗" aria-label="Permalink to “Q8：能力位（Capability）是怎么工作的？是运行时检查吗？”">​</a></h3><p><strong>A</strong>：<strong>不是运行时检查，是物理剔除。</strong></p><ul><li>创建实例时，未被授予的能力对应的<strong>原生函数根本不会注册到 JS 引擎的 <em><strong>Context</strong></em> 中</strong>。</li><li>如果 JS 代码尝试调用，会直接报 <em><strong>TypeError: xxx is not a function</strong></em>，<strong>不会触发任何“权限不足”的运行时开销</strong>。</li><li>性能零损耗，且无法通过原型链篡改绕过。</li></ul><h3 id="q9-能力位未定义的能力-会触发审核回调-audit-callback-吗" tabindex="-1">Q9：能力位未定义的能力，会触发审核回调（Audit Callback）吗？ <a class="header-anchor" href="#q9-能力位未定义的能力-会触发审核回调-audit-callback-吗" aria-label="Permalink to “Q9：能力位未定义的能力，会触发审核回调（Audit Callback）吗？”">​</a></h3><p><strong>A</strong>：<strong>不会。</strong> 因为函数根本不存在，审核回调找不到拦截目标。审核回调只作用于 <strong>“已被能力位授予，但额外开启了审核掩码”</strong> 的 API。</p><h3 id="q10-我通过-koss-register-function-注入的宿主函数-受能力位控制吗" tabindex="-1">Q10：我通过 <em><strong>koss_register_function</strong></em> 注入的宿主函数，受能力位控制吗？ <a class="header-anchor" href="#q10-我通过-koss-register-function-注入的宿主函数-受能力位控制吗" aria-label="Permalink to “Q10：我通过 koss_register_function 注入的宿主函数，受能力位控制吗？”">​</a></h3><p><strong>A</strong>：<strong>不受。</strong> 因为能力位只在初始化时控制“哪些 Rust 原生绑定要挂载”。宿主注入是实例创建后的动态行为，如果能力位能事后剔除宿主函数，那这个注入功能本身就是矛盾的。</p><p><strong>注意</strong>：虽然不受能力位控制，但<strong>审核回调（Audit Callback）仍然可以对宿主注入的函数生效</strong>（例如审核参数路径是否在安全目录内）。你可以利用审核回调实现“读取特定文件”等精细权限控制。</p><hr><h2 id="_5-平台支持" tabindex="-1">5. 平台支持 <a class="header-anchor" href="#_5-平台支持" aria-label="Permalink to “5. 平台支持”">​</a></h2><h3 id="q11-kossjs-在桌面端-windows-linux-macos-表现如何" tabindex="-1">Q11：KossJS 在桌面端（Windows/Linux/macOS）表现如何？ <a class="header-anchor" href="#q11-kossjs-在桌面端-windows-linux-macos-表现如何" aria-label="Permalink to “Q11：KossJS 在桌面端（Windows/Linux/macOS）表现如何？”">​</a></h3><p><strong>A</strong>：<strong>相对最稳定。</strong> 作者在这三个平台有测试环境，JS Shim 层和基础 C ABI 已经过充分验证。如果只使用 <em><strong>stable=True</strong></em> 模式（不碰 FFI），可以作为脚本引擎集成。</p><h3 id="q12-android-和-harmonyos-能用吗" tabindex="-1">Q12：Android 和 HarmonyOS 能用吗？ <a class="header-anchor" href="#q12-android-和-harmonyos-能用吗" aria-label="Permalink to “Q12：Android 和 HarmonyOS 能用吗？”">​</a></h3><p><strong>A</strong>：<strong>历史版本（dev.5）测试过，最新版本尚未测试。</strong> 可能存在回归风险，但架构上可行。欢迎有设备的开发者帮忙测试并反馈结果。</p><h3 id="q13-ios-能上-app-store-吗" tabindex="-1">Q13：iOS 能上 App Store 吗？ <a class="header-anchor" href="#q13-ios-能上-app-store-吗" aria-label="Permalink to “Q13：iOS 能上 App Store 吗？”">​</a></h3><p><strong>A</strong>：<strong>不能，且作者没打算支持。</strong></p><ul><li>作者明确表示 iOS 动态库仅用于内部测试使用。</li><li>如果企业内部分发（不需上架）可以自行签名折腾；但面向公众的 App Store 应用，<strong>请勿依赖 KossJS</strong>。</li></ul><hr><h2 id="_6-贡献与社区" tabindex="-1">6. 贡献与社区 <a class="header-anchor" href="#_6-贡献与社区" aria-label="Permalink to “6. 贡献与社区”">​</a></h2><h3 id="q14-我不会-rust-能帮上什么忙" tabindex="-1">Q14：我不会 Rust，能帮上什么忙？ <a class="header-anchor" href="#q14-我不会-rust-能帮上什么忙" aria-label="Permalink to “Q14：我不会 Rust，能帮上什么忙？”">​</a></h3><p><strong>A</strong>：<strong>能！</strong> 作者最缺的反而是 <strong>JavaScript 和 Python 方向的贡献者</strong>：</p><ul><li>审查 <em><strong>src/js_shims/</strong></em> 里的 Node/Bun/Deno 兼容层代码逻辑。</li><li>编写或完善 <em><strong>kossjs_interface.py</strong></em> 的 Python 测试用例。</li><li>补充文档和示例代码。</li></ul><h3 id="q15-我懂-rust-想帮忙-从哪里开始" tabindex="-1">Q15：我懂 Rust，想帮忙，从哪里开始？ <a class="header-anchor" href="#q15-我懂-rust-想帮忙-从哪里开始" aria-label="Permalink to “Q15：我懂 Rust，想帮忙，从哪里开始？”">​</a></h3><p><strong>A</strong>：作者原话：“不清楚”<br> 以下是基于当前源码（dev.10）的社区建议审查重点：</p><ul><li><p><em><strong>src/runtime.rs</strong></em></p><ul><li>所有 <em><strong>extern &quot;C&quot;</strong></em> 导出的 C ABI 函数（如 <em><strong>koss_eval</strong></em>、<em><strong>koss_run_async</strong></em> 等）目前<strong>没有</strong> <em><strong>catch_unwind</strong></em> 保护，Rust panic 会直接跨 FFI 边界导致宿主进程崩溃。建议在每一个导出函数入口处添加 <em><strong>std::panic::catch_unwind</strong></em> 并返回合理的错误结果。</li><li>Boa 引擎与 Tokio 异步运行时的桥接逻辑（<em><strong>KossEventLoop::process_io_results</strong></em> 中的 <em><strong>block_on</strong></em>、<em><strong>spawn</strong></em> 等），需要检查是否存在嵌套运行时阻塞或死锁风险。</li></ul></li><li><p><em><strong>src/sandbox.rs</strong></em></p><ul><li>能力位（Capability）和审核回调（Audit）的实现逻辑，注意审核回调是同步的，若用户回调执行耗时操作会阻塞事件循环，文档中应明确警告。</li></ul></li><li><p><em><strong>src/module_loader.rs</strong></em> 与 <em><strong>src/resolver.rs</strong></em></p><ul><li>模块加载和路径解析涉及文件系统访问，需检查路径遍历（Path Traversal）漏洞，确保 <em><strong>normalize_path</strong></em> 能正确防止 <em><strong>..</strong></em> 逃逸。</li></ul></li><li><p><em><strong>src/_senri_ffi/</strong></em> 目录</p><ul><li>FFI 实现（桌面端可用），但作者明确不推荐使用，若需要可审查其内存安全和跨平台兼容性。</li></ul></li></ul><hr><h2 id="_7-其他" tabindex="-1">7. 其他 <a class="header-anchor" href="#_7-其他" aria-label="Permalink to “7. 其他”">​</a></h2><h3 id="q16-作者不懂-rust-为什么要使用-rust" tabindex="-1">Q16：作者不懂 Rust 为什么要使用 Rust ？ <a class="header-anchor" href="#q16-作者不懂-rust-为什么要使用-rust" aria-label="Permalink to “Q16：作者不懂 Rust 为什么要使用 Rust ？”">​</a></h3><p><strong>A</strong>：作者本人并不熟悉系统级编程语言（如 C、C++、Rust），但项目本身需要在宿主程序中嵌入一个现代的 JavaScript 运行时。经过技术选型，Rust 生态下的 Boa 引擎在性能、跨平台支持以及通过 C ABI 暴露接口的便利性上，最符合项目的技术目标。</p><p>该项目最初是为了满足作者自身的实际开发需求而创建的。选择开源，是“顺手的事情”，同时让项目真正变得对社区可用。</p><h3 id="q17-本项目的许可证解读是什么" tabindex="-1">Q17：本项目的许可证解读是什么？ <a class="header-anchor" href="#q17-本项目的许可证解读是什么" aria-label="Permalink to “Q17：本项目的许可证解读是什么？”">​</a></h3><p><strong>A</strong>：简单来说：<strong>用官方发布的二进制库，闭源商用是允许的。</strong></p><p>KossJS 用的是 <strong>AGPL v3.0</strong>，但作者加了一条 <strong>“独立模块闭源组合例外”</strong>（附加权限）。只要满足三个条件，你的业务代码就不用开源：</p><ol><li><strong>用官方发布的库</strong>：必须用作者官方发布的 <em><strong>.dll/.so/.dylib</strong></em>，不能自己编译。</li><li><strong>不改官方库</strong>：官方发布的二进制文件中的二进制内容并未被修改。</li><li><strong>加一句声明</strong>：在你的软件“关于”页面、README 或用户手册等用户可看到的界面里加一句： <blockquote><p>“本软件使用了 <a href="./项目URL.html">KossJS</a> ，遵循 GNU AGPL v3.0 协议及 TT23XR Studio 的附加权限。”</p></blockquote></li></ol><h4 id="什么情况下必须开源" tabindex="-1">什么情况下必须开源？ <a class="header-anchor" href="#什么情况下必须开源" aria-label="Permalink to “什么情况下必须开源？”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">你的操作</th><th style="text-align:left;">后果</th></tr></thead><tbody><tr><td style="text-align:left;">用官方发布的二进制库，闭源集成</td><td style="text-align:left;">合规，只需署名</td></tr><tr><td style="text-align:left;">修改了 KossJS 源代码</td><td style="text-align:left;">必须把<strong>你自己修改后的代码</strong>以 AGPL 开源</td></tr><tr><td style="text-align:left;">自己从源码编译（即使没改代码）</td><td style="text-align:left;">必须遵守完整的 AGPL v3.0</td></tr><tr><td style="text-align:left;">把 KossJS 源码直接放进你的项目</td><td style="text-align:left;">必须遵守完整的 AGPL v3.0</td></tr></tbody></table><h4 id="额外注意" tabindex="-1">额外注意 <a class="header-anchor" href="#额外注意" aria-label="Permalink to “额外注意”">​</a></h4><ul><li><strong>第三方库不受影响</strong>：KossJS 依赖的 Boa、Tokio 等库有自己的许可证（MIT、Apache 等），按它们的规矩来。</li><li><strong>商业许可</strong>：作者目前不卖商业许可。有特殊需求得等作者成年后再联系。</li><li><strong>静态链接</strong>：有争议，<strong>建议用动态链接</strong>，别给自己找麻烦。</li></ul><h4 id="一句话总结" tabindex="-1">一句话总结： <a class="header-anchor" href="#一句话总结" aria-label="Permalink to “一句话总结：”">​</a></h4><p>用官方发布的 <em><strong>.dll/.so/.dylib</strong></em>，加一句声明，就可以闭源商用</p><hr><h2 id="_8-总结性建议" tabindex="-1">8. 总结性建议 <a class="header-anchor" href="#_8-总结性建议" aria-label="Permalink to “8. 总结性建议”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">使用场景</th><th style="text-align:left;">推荐做法</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>内部工具、原型开发、学习研究</strong></td><td style="text-align:left;">直接使用 <em><strong>stable=True</strong></em> 模式，JS 逻辑和标准 Shim 层是可以使用的。</td></tr><tr><td style="text-align:left;"><strong>生产环境（桌面端）</strong></td><td style="text-align:left;">仅限 <em><strong>stable=True</strong></em>，且避开 FFI。原生能力走宿主封装。且标准 Shim 层可能存在问题。</td></tr><tr><td style="text-align:left;"><strong>生产环境（移动端/App Store）</strong></td><td style="text-align:left;">不建议。Android 需自行验证回归，iOS 直接放弃。</td></tr><tr><td style="text-align:left;"><strong>调用 C/C++ 动态库</strong></td><td style="text-align:left;">不用 <em><strong>_senri_ffi</strong></em>。在宿主层封装好，用 <em><strong>register_function</strong></em> 注入。</td></tr></tbody></table><hr><blockquote><p><strong>最后，作者想对大家说</strong>：“我知道这项目有很多不完美的地方，但所有源码均开源。欢迎会 Rust 的大佬来修，也欢迎所有人来提 Issues 和 PR。开源的意义就在于我们一起把它变好。”</p></blockquote>',72)])])}const f=r(o,[["render",n]]);export{c as __pageData,f as default};
